/**
 * UFC lane status — the product-state contract for the protected console.
 *
 * EVERY field is DERIVED from a committed artifact. A missing source renders UNKNOWN, never green
 * and never zero: "we could not read it" and "there is nothing" are different facts and only one of
 * them is a product state.
 *
 * WHY THIS EXISTS. The gate's `products` stage asks for cards generated by scheduled automation ON
 * THE PRODUCT-STATE CONTRACT. Until tonight UFC had neither half — build-ufc-ladder was in no
 * workflow at all, and nothing published the lane's state. A state nothing publishes is a state
 * nothing can be held to, which is how a ladder came to sit four days stale while every surface
 * reported the sport as live.
 *
 * INTERNAL. prune-internal-routes sweeps app/public/data by build reference, so this ships only to
 * the host-protected deployment. Declaring a lane's state is not a public claim.
 *
 * Usage: npx tsx scripts/ufc/build-ufc-lane-status.mjs --now <iso>   (from app/)
 * Writes: app/public/data/admin/ufc-lane.json
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { SPORT_ASSESSMENTS } from "../../src/lib/sports/sport-assessments.mjs";
import { deriveSportMaturity, remainingPath, GATE_STAGES } from "../../src/lib/sports/sport-gate.mjs";
import { labEligibility } from "../parlays/lab-eligibility.mjs";
import { loadOfficialUfcResults, fighterIndexForDate } from "../../src/lib/sports/ufc/official-results.mjs";

const APP = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
const ROOT = path.join(APP, "..");
const arg = (n, f = null) => { const i = process.argv.indexOf(n); return i !== -1 && process.argv[i + 1] ? process.argv[i + 1] : f; };
const NOW = arg("--now");
if (!NOW || !Number.isFinite(Date.parse(NOW))) { console.error("REFUSED: --now <ISO> required"); process.exit(1); }
const nowMs = Date.parse(NOW);

const read = (p) => { try { return JSON.parse(fs.readFileSync(p, "utf8")); } catch { return null; } };
const readText = (p) => { try { return fs.readFileSync(p, "utf8"); } catch { return null; } };
const UNKNOWN = (why) => ({ state: "UNKNOWN", detail: why });

const card = read(path.join(APP, "public/data/ufc/card-latest.json"));
const odds = read(path.join(APP, "public/data/ufc/odds-latest.json"));
const ladder = read(path.join(APP, "public/data/parlays/risk-ladder-ufc/latest.json"));
const results = read(path.join(APP, "public/data/ufc/results-latest.json"));
const settled = read(path.join(APP, "public/data/ufc/results-settled-latest.json"));
const ledger = read(path.join(ROOT, "data/internal/research/odds/ufc/authorization-ledger.json"));
const receipt = readText(path.join(ROOT, "docs/receipts/ODDS_AUTHORIZATION_UFC.md"));

/** Age by an artifact's OWN stamp — never a file mtime, which records when git touched it. */
const freshnessOf = (label, artifact, keys) => {
  if (!artifact) return UNKNOWN(`no ${label} artifact`);
  const stamp = keys.map((k) => artifact[k]).find((v) => typeof v === "string" && Number.isFinite(Date.parse(v)));
  if (!stamp) return UNKNOWN(`${label} carries no readable stamp`);
  return { state: "READ", stampedAt: stamp, ageHours: Number(((nowMs - Date.parse(stamp)) / 3.6e6).toFixed(2)) };
};

const slate = card?.event?.slateDate ?? null;
const nextCard = card?.state === "SCHEDULED_CARD" && card.event
  ? {
      name: card.event.name ?? null,
      slateDate: slate,
      bouts: card.event.boutCount ?? null,
      hoursAway: card.event.startUtc ? Number(((Date.parse(card.event.startUtc) - nowMs) / 3.6e6).toFixed(2)) : null,
    }
  : UNKNOWN(`no scheduled card (state ${card?.state ?? "absent"})`);

/*
 * THE LADDER MUST BELONG TO THE CARD ON THE PAGE.
 *
 * A ladder written on 2026-08-18 for an event on 2026-08-22 was being served through a latest.json
 * fallback and published under 2026-08-21 — three dates for one set of cards. The check is one
 * comparison and it is the difference between a product and a stale artifact wearing today's name.
 */
const cards = ladder
  ? (ladder.date === slate
      ? { state: "PUBLISHED_FOR_THIS_CARD", date: ladder.date, carded: (ladder.cards ?? []).length, skipped: (ladder.skipped ?? []).map((s) => s.tier), selection: ladder.selection ?? null }
      : { state: "STALE_FOR_A_DIFFERENT_CARD", detail: `the newest ladder is dated ${ladder.date} but this card is on ${slate ?? "an unknown date"}` })
  : UNKNOWN("no risk ladder has been published");

/*
 * Whether the settler can even see this sport's cards — the defect that made every UFC card
 * ungradeable.
 *
 * THE DATE HALF IS NOW PROVEN BY RUNNING IT, NOT BY GREPPING FOR IT. This searched the settler's
 * source for the literal `r.eventDate !== DATE`. That confinement moved into the shared official-
 * results reader when the settler was taught to read BOTH results sources, and the grep went on
 * looking for it where it used to be — so this artifact published OUT_OF_SCOPE, asserting the
 * settler could not reach UFC, hours after it had settled a UFC card. A guard that reports a
 * capability as absent because the code was reorganised is worse than no guard, because it is a
 * false alarm on a settlement path and false alarms there get ignored.
 *
 * A rename cannot break a probe that feeds the real function a fighter who appears on two different
 * cards and checks that only the settled one comes back.
 */
const settlementReach = (() => {
  const src = readText(path.join(APP, "scripts/parlays/settle-lab-cards.mjs"));
  if (!src) return UNKNOWN("the lab settler could not be read");
  const reads = /risk-ladder-ufc/.test(src);
  let dated = false;
  try {
    const probe = loadOfficialUfcResults({
      corpus: { results: [
        { eventDate: "2099-01-01", fighterA: "Probe One", fighterB: "Probe Two", winner: "Probe One", loser: "Probe Two" },
        { eventDate: "2099-06-01", fighterA: "Probe Two", fighterB: "Probe One", winner: "Probe Two", loser: "Probe One" },
      ] },
    });
    const jan = fighterIndexForDate(probe.byBout, "2099-01-01");
    const jun = fighterIndexForDate(probe.byBout, "2099-06-01");
    // The same fighter wins one card and loses the other. If the index were unconfined, one result
    // would overwrite the other and both days would agree — which is the fabrication being ruled out.
    dated = jan.get("probe one")?.won === true && jun.get("probe one")?.won === false;
  } catch { dated = false; }
  return {
    state: reads && dated ? "IN_SCOPE" : "OUT_OF_SCOPE",
    readsUfcLadder: reads,
    /* Without this, a fighter's name matched anywhere in a 126-event corpus and graded a fight that
       had not happened. It is the difference between a settled record and a fabricated one. */
    constrainedToCardDate: dated,
    provenBy: "a live probe of the shared results reader, not a text match on the settler",
  };
})();

const CEILING = Number(/(\d+)\s+credits/.exec(receipt ?? "")?.[1] ?? 0) || null;
const credits = ledger && CEILING
  ? { state: "READ", spent: ledger.cumulativeCredits ?? 0, ceiling: CEILING, requests: (ledger.requests ?? []).length }
  : UNKNOWN("no ledger or receipt — spend cannot be reported");

const stages = SPORT_ASSESSMENTS.ufc.stages;
const maturity = deriveSportMaturity(stages, SPORT_ASSESSMENTS.ufc);
const proven = GATE_STAGES.filter((s) => stages[s.id]?.status === "PROVEN").length;

const lane = (() => {
  try {
    const me = (labEligibility(path.join(APP, "public", "data"), NOW.slice(0, 10), NOW) ?? []).find((x) => x.id === "ufc");
    return me ? { live: me.live, blocked: me.blocked ?? null } : null;
  } catch { return null; }
})();

const blockers = [];
if (settlementReach.state !== "IN_SCOPE") {
  blockers.push({ id: "settler-cannot-grade-ufc", state: "ENGINEERING", detail: "the lab settler does not read this sport's ladder, or does not constrain results to the card's own date. Cards would publish and never grade." });
}
if (cards.state === "STALE_FOR_A_DIFFERENT_CARD") {
  blockers.push({ id: "ladder-stale", state: "ENGINEERING", detail: cards.detail });
}
if ((stages.calibration?.status ?? "UNPROVEN") !== "PROVEN") {
  blockers.push({ id: "calibration-sample", state: "REALITY_GATED", detail: "the model has never been scored against a no-vig UFC line, and one card has been settled from official results. Cards have to be fought." });
}
if ((stages.data?.status ?? "UNPROVEN") !== "PROVEN") {
  blockers.push({ id: "corpus-is-historical", state: "REALITY_GATED", detail: "the fight corpus is historical and winner-only; a live per-card feed with method and round is not authorised. Clears as forward captures accumulate." });
}
if (lane == null) blockers.push({ id: "product-lane-unknown", state: "ENGINEERING", detail: "the Lab eligibility gate could not be evaluated — unknown is not closed." });
else if (!lane.live) blockers.push({ id: "product-lane-closed", state: "REALITY_GATED", detail: `the Lab gate has closed this lane: ${lane.blocked}. It reopens by itself when the evidence returns.` });

const out = {
  schemaVersion: 1,
  artifact: "ufc-lane-status",
  dataClass: "INTERNAL_ADMIN",
  generatedAt: NOW,
  nextCard,
  freshness: {
    card: freshnessOf("card", card, ["generatedAt"]),
    odds: freshnessOf("odds", odds, ["generatedAt", "capturedAt"]),
    ladder: freshnessOf("ladder", ladder, ["generatedAt"]),
    results: freshnessOf("results", results, ["generatedAt"]),
    settled: freshnessOf("settlement", settled, ["settledAt", "generatedAt"]),
  },
  cards,
  settlementReach,
  credits,
  productLane: lane,
  gate: { maturity, proven, of: GATE_STAGES.length, remaining: remainingPath(stages, SPORT_ASSESSMENTS.ufc).map((r) => ({ stage: r.stage, status: r.status, requiredProof: r.requiredProof })) },
  blockers,
};

const dir = path.join(APP, "public/data/admin");
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(path.join(dir, "ufc-lane.json"), `${JSON.stringify(out, null, 2)}\n`);

console.log(`ufc lane: ${maturity} · ${proven}/${GATE_STAGES.length} stages proven · ${blockers.length} blocker(s)`);
console.log(`  next card: ${nextCard.name ?? "—"}${nextCard.slateDate ? ` on ${nextCard.slateDate}` : ""}`);
console.log(`  cards: ${cards.state}${cards.carded != null ? ` · ${cards.carded} carded, skipped ${cards.skipped.join(", ") || "none"}` : ""}`);
console.log(`  settler reach: ${settlementReach.state} (reads ladder ${settlementReach.readsUfcLadder}, date-constrained ${settlementReach.constrainedToCardDate})`);
console.log(`  credits: ${credits.spent ?? "?"}/${credits.ceiling ?? "?"}`);
for (const b of blockers) console.log(`  blocker ${b.state.padEnd(14)} ${b.id}`);
